ALTER TABLE invoices ADD COLUMN IF NOT EXISTS lead_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS title VARCHAR(255) NULL, ADD COLUMN IF NOT EXISTS discount DECIMAL(15,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS tax DECIMAL(15,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS amount_paid DECIMAL(15,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS balance_due DECIMAL(15,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS terms TEXT NULL, ADD COLUMN IF NOT EXISTS public_token CHAR(64) NULL;
ALTER TABLE invoice_items ADD COLUMN IF NOT EXISTS amount DECIMAL(15,2) NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS uq_invoice_public_token ON invoices(public_token);
